$ErrorActionPreference = "Stop"

$root = Split-Path -Parent $PSScriptRoot
$utf8 = New-Object System.Text.UTF8Encoding($false)

function Decode([string]$Value) {
    return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value))
}

$helper = Decode ""
$importBlock = Decode "aW1wb3J0IHsKICB2YWxpZGF0ZVByb3ZpZGVyTGl2ZU11bHRpU2xvdENvdmVyYWdlLAp9IGZyb20gIkAvbGliL211bHRpLXNsb3QtbGl2ZS1jb3ZlcmFnZSI7Cg=="
$liveGuard = Decode ""

$helperPath = Join-Path $root "lib\multi-slot-live-coverage.ts"
$routePath = Join-Path $root "app\api\market\requests\[id]\offers\route.ts"
$providerJobsPath = Join-Path $root "app\api\provider\jobs\route.ts"

foreach ($path in @($routePath, $providerJobsPath)) {
    if (-not (Test-Path -LiteralPath $path)) {
        throw "12.95 : fichier requis introuvable : $path"
    }
}

$route = [System.IO.File]::ReadAllText($routePath)
$providerJobs = [System.IO.File]::ReadAllText($providerJobsPath)

if (-not $route.Contains("KLYX_MULTI_SLOT_OFFER_SERVER_GUARD_12_94")) {
    throw "12.95 : protection serveur 12.94 introuvable."
}

if (-not $providerJobs.Contains("KLYX_PROVIDER_MULTI_JOBS_API_12_93")) {
    throw "12.95 : Provider Jobs 12.93 introuvable."
}

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"

Copy-Item -LiteralPath $routePath -Destination ($routePath + ".bak-12-95-" + $timestamp) -Force

if (Test-Path -LiteralPath $helperPath) {
    Copy-Item -LiteralPath $helperPath -Destination ($helperPath + ".bak-12-95-" + $timestamp) -Force
}

[System.IO.File]::WriteAllText($helperPath, $helper, $utf8)

# ===========================================================
# IMPORT
# ===========================================================

if (-not $route.Contains("validateProviderLiveMultiSlotCoverage")) {
    $importAnchor = 'import { supabaseAdmin } from "@/lib/supabase-admin";'

    $importIndex = $route.IndexOf($importAnchor)

    if ($importIndex -lt 0) {
        throw "12.95 : import supabaseAdmin introuvable."
    }

    $insertAt = $importIndex + $importAnchor.Length

    $route = $route.Insert($insertAt, "`r`n" + $importBlock.TrimEnd())
}

# ===========================================================
# LIVE GUARD
# ===========================================================

if (-not $route.Contains("KLYX_MULTI_SLOT_LIVE_OFFER_GUARD_12_95")) {
    $offerAnchor = "    const { data: offer, error } = await supabaseAdmin"

    $offerIndex = $route.IndexOf($offerAnchor)

    if ($offerIndex -lt 0) {
        throw "12.95 : ancre upsert offre introuvable."
    }

    $guard94 = $route.IndexOf("KLYX_MULTI_SLOT_OFFER_SERVER_GUARD_12_94")

    if ($guard94 -lt 0 -or $guard94 -gt $offerIndex) {
        throw "12.95 : ordre du guard 12.94 invalide."
    }

    $route = $route.Insert($offerIndex, $liveGuard)
}

[System.IO.File]::WriteAllText($routePath, $route, $utf8)

Write-Host ""
Write-Host "======================================"
Write-Host "KLYX 12.95 APPLIQUE"
Write-Host "======================================"
Write-Host "Snapshot candidat 12.94 : CONSERVE"
Write-Host "Disponibilite live : VERIFIEE"
Write-Host "Conflits bookings : VERIFIES"
Write-Host "Planning modifie apres matching : DETECTE"
Write-Host "Candidat stale : RESYNCHRONISE"
Write-Host "Offre sans N/N live : BLOQUEE"
Write-Host "Execution automatique : NON"
Write-Host "======================================"
